/* ===== Monzo — 100 native facets (data-spectrum="monzo"). Token-driven, self-contained. ===== */
.monzo-root{--monzo-radius:12px;--monzo-font:"Segoe UI", system-ui, -apple-system, Roboto, Helvetica, Arial, sans-serif;font-family:var(--monzo-font,inherit)}
@keyframes monzoBtnPulse{0%,100%{box-shadow:0 0 0 0 rgba(var(--_rgb),.5)}50%{box-shadow:0 0 0 6px rgba(var(--_rgb),0)}}
.monzo-btn{display:inline-flex;align-items:center;gap:8px;padding:9px 18px;border-radius:var(--monzo-radius,999px);background:var(--_c);color:#fff;font-weight:700;border:0;animation:monzoBtnPulse 2.4s ease-in-out infinite}
@keyframes monzoTgKnob{0%,100%{left:2px}50%{left:20px}}
.monzo-toggle{position:relative;width:44px;height:24px;border-radius:999px;background:rgba(var(--_rgb),.28);border:1px solid rgba(var(--_rgb),.5)}
.monzo-toggle::after{content:"";position:absolute;top:2px;left:2px;width:18px;height:18px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.7);animation:monzoTgKnob 2.6s ease-in-out infinite}
@keyframes monzoChipShine{0%{background-position:-160% 0}60%,100%{background-position:260% 0}}
.monzo-chip{position:relative;overflow:hidden;display:inline-flex;align-items:center;padding:4px 12px;border-radius:999px;background:rgba(var(--_rgb),.16);border:1px solid rgba(var(--_rgb),.4);color:var(--_c);font-size:12px;font-weight:700}
.monzo-chip::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 40%,rgba(var(--_rgb),.4) 50%,transparent 60%);background-size:250% 100%;animation:monzoChipShine 3s linear infinite;pointer-events:none}
@keyframes monzoMenuSel{0%,100%{background:rgba(var(--_rgb),.12)}50%{background:rgba(var(--_rgb),.26)}}
.monzo-menu{min-width:150px;padding:6px;border-radius:var(--monzo-radius,12px);background:var(--panel2);border:1px solid var(--line)}
.monzo-menu .monzo-mi{padding:7px 10px;border-radius:8px;color:var(--ink);font-size:12px}
.monzo-menu .monzo-sel{color:var(--_c);animation:monzoMenuSel 2.8s ease-in-out infinite}
@keyframes monzoNotifIn{0%,100%{transform:translateX(-6px);opacity:.75}50%{transform:translateX(0);opacity:1}}
.monzo-toast{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;background:var(--panel2);border:1px solid var(--line);border-left:3px solid var(--_c);color:var(--ink);font-size:12px;animation:monzoNotifIn 3s ease-in-out infinite}
.monzo-toast::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.8)}
@keyframes monzoCalloutEdge{0%{transform:translateX(-120%)}100%{transform:translateX(120%)}}
.monzo-callout{position:relative;overflow:hidden;padding:10px 14px;border-radius:10px;background:rgba(var(--_rgb),.1);border:1px solid rgba(var(--_rgb),.35);color:var(--ink);font-size:12px}
.monzo-callout::after{content:"";position:absolute;top:0;left:0;height:2px;width:60%;background:linear-gradient(90deg,transparent,var(--_c),transparent);animation:monzoCalloutEdge 2.6s linear infinite;pointer-events:none}
@keyframes monzoBarGrow{0%{transform:scaleY(.25)}50%{transform:scaleY(1)}100%{transform:scaleY(.25)}}
.monzo-chart{display:flex;align-items:flex-end;gap:5px;height:44px;padding:6px 8px;border-radius:10px;background:var(--panel2);border:1px solid var(--line)}
.monzo-chart i{flex:1;background:var(--_c);border-radius:3px 3px 0 0;transform-origin:bottom;animation:monzoBarGrow 2.4s ease-in-out infinite}
.monzo-chart i:nth-child(2){animation-delay:.2s}.monzo-chart i:nth-child(3){animation-delay:.4s}.monzo-chart i:nth-child(4){animation-delay:.6s}
@keyframes monzoInputCaret{0%,49%{opacity:1}50%,100%{opacity:0}}
.monzo-field{display:inline-flex;align-items:center;gap:2px;min-width:150px;padding:8px 11px;border-radius:10px;background:var(--panel);border:1px solid var(--_c);box-shadow:0 0 0 3px rgba(var(--_rgb),.18);color:var(--ink);font-size:12px}
.monzo-field .monzo-caret{width:1.5px;height:14px;background:var(--_c);animation:monzoInputCaret 1.1s step-end infinite}
@keyframes monzoProg{0%{width:8%}80%,100%{width:96%}}
.monzo-prog{width:150px;height:8px;border-radius:999px;background:rgba(var(--_rgb),.18);overflow:hidden}
.monzo-prog i{display:block;height:100%;border-radius:inherit;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:monzoProg 3s ease-in-out infinite}
@keyframes monzoAvRing{to{transform:rotate(1turn)}}
.monzo-avatar{position:relative;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:var(--panel2);color:var(--ink);font-weight:800}
.monzo-avatar::before{content:"";position:absolute;inset:-3px;border-radius:50%;background:conic-gradient(from 0deg,var(--_c),transparent 55%,var(--_c));-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));animation:monzoAvRing 3.4s linear infinite}
@keyframes monzoBadgePop{0%,100%{transform:scale(1)}30%{transform:scale(1.25)}}
.monzo-badge{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 6px;border-radius:999px;background:var(--_c);color:#fff;font-size:11px;font-weight:800;animation:monzoBadgePop 2s ease-in-out infinite}
@keyframes monzoTabSlide{0%,100%{left:2px}50%{left:calc(50% + 1px)}}
.monzo-tabs{position:relative;display:inline-flex;padding:3px;border-radius:999px;background:var(--panel2);border:1px solid var(--line)}
.monzo-tabs span{position:relative;z-index:1;padding:5px 14px;font-size:12px;color:var(--ink)}
.monzo-tabs::before{content:"";position:absolute;top:3px;bottom:3px;width:calc(50% - 3px);left:2px;border-radius:999px;background:rgba(var(--_rgb),.9);animation:monzoTabSlide 3.2s ease-in-out infinite}
@keyframes monzoTipFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.monzo-tip{display:inline-block;padding:6px 10px;border-radius:8px;background:var(--panel2);border:1px solid var(--_c);color:var(--ink);font-size:11px;box-shadow:0 4px 14px rgba(var(--_rgb),.3);animation:monzoTipFloat 2.6s ease-in-out infinite}
@keyframes monzoSpin{to{transform:rotate(1turn)}}
.monzo-spinner{width:26px;height:26px;border-radius:50%;border:3px solid rgba(var(--_rgb),.22);border-top-color:var(--_c);animation:monzoSpin 1s linear infinite}
@keyframes monzoCardGlow{0%,100%{box-shadow:0 0 0 1px var(--line)}50%{box-shadow:0 0 16px rgba(var(--_rgb),.4)}}
.monzo-card{width:150px;padding:12px;border-radius:var(--monzo-radius,12px);background:var(--card);color:var(--ink);animation:monzoCardGlow 3.4s ease-in-out infinite}
.monzo-card b{color:var(--_c);font-size:12px}.monzo-card p{margin:4px 0 0;font-size:11px;color:var(--muted)}
@keyframes monzoCheckIn{0%,20%{clip-path:inset(0 100% 0 0)}60%,100%{clip-path:inset(0 0 0 0)}}
.monzo-check{position:relative;width:22px;height:22px;border-radius:6px;background:var(--_c);display:grid;place-items:center}
.monzo-check::after{content:"✓";color:#fff;font-size:14px;font-weight:900;animation:monzoCheckIn 2.4s ease-in-out infinite}
@keyframes monzoSliderThumb{0%,100%{left:2px}50%{left:calc(100% - 16px)}}
.monzo-slider{position:relative;width:150px;height:6px;border-radius:999px;background:rgba(var(--_rgb),.2)}
.monzo-slider::before{content:"";position:absolute;top:-5px;left:2px;width:16px;height:16px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:monzoSliderThumb 3s ease-in-out infinite}
@media(prefers-reduced-motion:reduce){.monzo-root [class*="monzo-"],.monzo-root [class*="monzo-"]::before,.monzo-root [class*="monzo-"]::after,.monzo-root [class],.monzo-root [class]::before,.monzo-root [class]::after{animation:none!important}}

